API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Router_and_Request_Dispatcher, "Router and Request Dispatcher", "Amazon API Gateway", "Manages routing, security, and throttling for incoming API requests.")
    Component(Security_and_Auth_Validator, "Security and Auth Validator", "AWS Lambda Authorizers / Lambda@Edge", "Performs edge logic and stateless JWT validation.")
}

Rel(Router_and_Request_Dispatcher, Security_and_Auth_Validator, "Validates requests using")

@enduml

Database (DynamoDB).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Database (DynamoDB) container

Container_Boundary("Database (DynamoDB)", "Database (DynamoDB)") {
    Component(Catalog Table (Books), "Catalog Table (Books)", "Amazon DynamoDB", "Stores catalogue data for physical and electronic books.")
    Component(Global Secondary Indexes (SearchIndex), "Global Secondary Indexes (SearchIndex)", "Amazon DynamoDB GSI", "Provides secondary access patterns for fast searching.")
    Component(DynamoDB Streams with AWS Lambda, "DynamoDB Streams with AWS Lambda", "DynamoDB Streams, AWS Lambda", "Captures change data events and triggers asynchronous processing.")
}

Rel(Catalog Table (Books), Global Secondary Indexes (SearchIndex), "Indexes data for search operations")
Rel(Catalog Table (Books), DynamoDB Streams with AWS Lambda, "Triggers change data capture events")

@enduml

Cache (ElastiCache Redis).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Person_Ext(recommendationservice, "Recommendation Service", "Python, FastAPI service that provides book recommendations.")
System_Ext(messagebroker, "Message Broker", "Amazon SQS, Amazon SNS, Amazon EventBridge")

Container_Boundary(cache, "Cache (ElastiCache Redis)") {
    Component(RecommendationCacheComponent, "Recommendation Cache Component", "Redis, ElastiCache", "Caches book recommendations for fast retrieval by the Recommendation Service.")
    Component(SessionStoreComponent, "Session Store Component", "Redis, ElastiCache", "Stores user session data for authentication and state management.")
}

Rel(recommendationservice, RecommendationCacheComponent, "Reads and writes recommendation data", "Redis Protocol")
Rel(messagebroker, RecommendationCacheComponent, "Triggers cache invalidation", "AMQP/SNS topics")
@enduml
